/**
 * A zombie pose seen from a view other than S.
 *
 * Every view of every pose is a validated drawing in hero64.poses.views.ts
 * (generated by scripts/research/gen_pose_views.py): W, SW and N bodies are
 * hand-drawn where the pose needs it, the rest is derived there from the S
 * body (SW: the S body with the three-quarter head; N: flipped and flattened
 * with the N head; NW: the back of the SW drawing). The head may sit behind
 * the body (a hump hides the nape); the body cells then stay in front of hair
 * and hats through `form.front`.
 *
 * Mirrored poses (`*_m`) carry their own back view (flipped, as their S view
 * is) and share the base pose's W, SW and NW drawings (D-042: a mirrored view
 * keeps the drawn side).
 */
import { parseSprite } from './format.js';
import type { HeroView } from './hero64.js';
import type { ZombiePose } from './hero64.poses.js';
import { POSE_VIEW_DATA } from './hero64.poses.views.js';
import { STAND_VIEWS } from './views64.js';

type PoseRegions = Omit<ZombiePose, 'id' | 'form' | 'w'>;

export function poseInView(pose: ZombiePose, view: HeroView): ZombiePose | undefined {
  if (view === 'S') return pose;
  if (pose.id === 'stand') return STAND_VIEWS[view];
  const baseId = pose.id.endsWith('_m') ? pose.id.slice(0, -2) : pose.id;
  const d = POSE_VIEW_DATA[pose.id]?.[view] ?? POSE_VIEW_DATA[baseId]?.[view];
  if (!d) return undefined;
  const id = `${pose.id}_${view}`;
  const figure = parseSprite(d.rows, id);
  const front = d.headUnder ? parseSprite(d.body, `${id}_body`) : undefined;
  return {
    id,
    form: {
      id,
      label: `${pose.form.label} (${view})`,
      figure,
      headMap: (x, y) => [x + d.headX + (d.shift[y] ?? 0), y + d.headY],
      ...(front ? { front } : {}),
    },
    w: figure.w,
    ...(d.regions as unknown as PoseRegions),
  };
}
